css:
/* ── 1. CIRCLE-CHECK: Circle pulses, checkmark pops ── */
.si-icon-cell:hover .u3cn0o .sf-circle-check-p0,
.icon-card:hover .u3cn0o .sf-circle-check-p0 {
  animation: nd4jkb 0.5s ease;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .u3cn0o .sf-circle-check-p1,
.icon-card:hover .u3cn0o .sf-circle-check-p1 {
  animation: x8k7nn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.15s both;
  transform-origin: 10px 14px;
}
@keyframes nd4jkb {
  0%, 100% { transform: scale(1); }
  40% { transform: scale(1.1); }
}
@keyframes x8k7nn {
  0% { transform: scale(1) rotate(0); }
  40% { transform: scale(1.3) rotate(-8deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 2. CIRCLE-X: Circle shakes, X pulses red-hot ── */
.si-icon-cell:hover .h7cmcm .sf-circle-x-p0,
.icon-card:hover .h7cmcm .sf-circle-x-p0 {
  animation: c5l7di 0.5s ease;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .h7cmcm .sf-circle-x-p1,
.icon-card:hover .h7cmcm .sf-circle-x-p1 {
  animation: un5uzx 0.5s ease;
  transform-origin: 12px 12px;
}
@keyframes c5l7di {
  0%, 100% { transform: translateX(0); }
  15% { transform: translateX(-3px); }
  30% { transform: translateX(3px); }
  45% { transform: translateX(-2px); }
  60% { transform: translateX(2px); }
  75% { transform: translateX(-1px); }
}
@keyframes un5uzx {
  0%, 100% { transform: scale(1); opacity: 1; }
  25% { transform: scale(1.3); opacity: 0.5; }
  50% { transform: scale(0.9); opacity: 1; }
  75% { transform: scale(1.1); opacity: 0.7; }
}

/* ── 3. ALERT-TRIANGLE: Urgent wobble with exclamation flash ── */
.si-icon-cell:hover .oscbag,
.icon-card:hover .oscbag {
  animation: sbl8iv 0.6s ease;
  transform-origin: center bottom;
}
.si-icon-cell:hover .oscbag .sf-alert-triangle-p0,
.icon-card:hover .oscbag .sf-alert-triangle-p0 {
  animation: c8g8m7 0.6s ease infinite;
}
@keyframes sbl8iv {
  0% { transform: rotate(0) scale(1); }
  10% { transform: rotate(-12deg) scale(1.05); }
  20% { transform: rotate(10deg) scale(1.05); }
  30% { transform: rotate(-8deg); }
  40% { transform: rotate(6deg); }
  50% { transform: rotate(-3deg); }
  60% { transform: rotate(1deg); }
  100% { transform: rotate(0) scale(1); }
}
@keyframes c8g8m7 {
  0%, 100% { opacity: 1; }
  30% { opacity: 0.2; }
  60% { opacity: 1; }
  80% { opacity: 0.4; }
}

/* ── 4. INFO-CIRCLE: i-dot bounces, line draws ── */
.si-icon-cell:hover .w1l339 .sf-info-circle-p1,
.icon-card:hover .w1l339 .sf-info-circle-p1 {
  animation: cumfav 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: 12px 9px;
}
.si-icon-cell:hover .w1l339 .sf-info-circle-p2,
.icon-card:hover .w1l339 .sf-info-circle-p2 {
  animation: mzbdrk 0.4s ease 0.2s both;
}
@keyframes cumfav {
  0% { transform: scale(1); }
  40% { transform: scale(2); }
  70% { transform: scale(0.8); }
  100% { transform: scale(1); }
}
@keyframes mzbdrk {
  0% { opacity: 0; transform: translateY(3px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* ── 5. HELP-CIRCLE: Question mark bounces curiously ── */
.si-icon-cell:hover .i134pb .sf-help-circle-p2,
.icon-card:hover .i134pb .sf-help-circle-p2 {
  animation: awlopf 0.7s ease;
  transform-origin: 12px 11px;
}
.si-icon-cell:hover .i134pb .sf-help-circle-p1,
.icon-card:hover .i134pb .sf-help-circle-p1 {
  animation: oslsbj 0.3s ease 0.35s both;
  transform-origin: 12px 16px;
}
@keyframes awlopf {
  0%, 100% { transform: rotate(0) translateY(0); }
  20% { transform: rotate(15deg) translateY(-2px); }
  40% { transform: rotate(-12deg) translateY(-1px); }
  60% { transform: rotate(6deg); }
  80% { transform: rotate(-3deg); }
}
@keyframes oslsbj {
  0% { transform: scale(0); }
  60% { transform: scale(1.5); }
  100% { transform: scale(1); }
}

/* ── 6. BAN: Circle shakes, strike throbs ── */
.si-icon-cell:hover .zjbzhs .sf-ban-p0,
.icon-card:hover .zjbzhs .sf-ban-p0 {
  animation: qi0r44 0.5s ease;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .zjbzhs .sf-ban-p1,
.icon-card:hover .zjbzhs .sf-ban-p1 {
  animation: x256ep 0.5s ease;
  transform-origin: 12px 12px;
}
@keyframes qi0r44 {
  0%, 100% { transform: scale(1) rotate(0); }
  20% { transform: scale(1.08) rotate(-5deg); }
  40% { transform: scale(1.08) rotate(5deg); }
  60% { transform: scale(1.04) rotate(-2deg); }
  80% { transform: scale(1.02) rotate(1deg); }
}
@keyframes x256ep {
  0%, 100% { transform: scale(1); opacity: 1; }
  30% { transform: scale(1.15); opacity: 0.6; }
  60% { transform: scale(0.95); opacity: 1; }
}

/* ── 7. CLOCK: Hand ticks with step motion ── */
.si-icon-cell:hover .lavfr1 .sf-clock-p1,
.icon-card:hover .lavfr1 .sf-clock-p1 {
  animation: fw9dqb 1.2s steps(12) infinite;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .lavfr1 .sf-clock-p0,
.icon-card:hover .lavfr1 .sf-clock-p0 {
  animation: of0ssz 1.2s ease infinite;
  transform-origin: center;
}
@keyframes fw9dqb {
  from { transform: rotate(0); }
  to { transform: rotate(360deg); }
}
@keyframes of0ssz {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.03); opacity: 0.8; }
}

/* ── 8. HOURGLASS: Full flip with sand settling ── */
.si-icon-cell:hover .yv1xld,
.icon-card:hover .yv1xld {
  animation: awxjm2 1s cubic-bezier(0.68, -0.55, 0.27, 1.55) infinite;
  transform-origin: center;
}
@keyframes awxjm2 {
  0% { transform: rotate(0) scale(1); }
  20% { transform: rotate(30deg) scale(1.05); }
  50% { transform: rotate(180deg) scale(0.95); }
  70% { transform: rotate(180deg) scale(1.02); }
  100% { transform: rotate(180deg) scale(1); }
}

/* ── 9. LOADER-2: Smooth continuous spin ── */
.si-icon-cell:hover .t8ub4c,
.icon-card:hover .t8ub4c {
  animation: s3n77z 0.8s linear infinite;
  transform-origin: center;
}
@keyframes s3n77z { to { transform: rotate(360deg); } }

/* ── 10. REFRESH: Bouncy spin with overshoot ── */
.si-icon-cell:hover .bz7gek,
.icon-card:hover .bz7gek {
  animation: xnbmph 0.7s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center;
}
@keyframes xnbmph {
  0% { transform: rotate(0) scale(1); }
  50% { transform: rotate(200deg) scale(0.9); }
  100% { transform: rotate(360deg) scale(1); }
}

/* ── 11. PROGRESS-CHECK: Ring spins, check bounces ── */
.si-icon-cell:hover .gyf67b .sf-progress-check-p0,
.icon-card:hover .gyf67b .sf-progress-check-p0 {
  animation: etp1l2 0.6s ease 0s both;
}
.si-icon-cell:hover .gyf67b .sf-progress-check-p1,
.icon-card:hover .gyf67b .sf-progress-check-p1 {
  animation: etp1l2 0.6s ease 0.08s both;
}
.si-icon-cell:hover .gyf67b .sf-progress-check-p2,
.icon-card:hover .gyf67b .sf-progress-check-p2 {
  animation: etp1l2 0.6s ease 0.16s both;
}
.si-icon-cell:hover .gyf67b .sf-progress-check-p3,
.icon-card:hover .gyf67b .sf-progress-check-p3 {
  animation: etp1l2 0.6s ease 0.24s both;
}
.si-icon-cell:hover .gyf67b .sf-progress-check-p4,
.icon-card:hover .gyf67b .sf-progress-check-p4 {
  animation: etp1l2 0.6s ease 0.32s both;
}
.si-icon-cell:hover .gyf67b .sf-progress-check-p5,
.icon-card:hover .gyf67b .sf-progress-check-p5 {
  animation: oq3y39 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.4s both;
  transform-origin: 12px 12px;
}
@keyframes etp1l2 {
  0%, 100% { opacity: 1; }
  40% { opacity: 0.2; }
  70% { opacity: 1; }
}
@keyframes oq3y39 {
  0% { transform: scale(1) rotate(0); }
  50% { transform: scale(1.3) rotate(-10deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 12. BELL: Ring with decaying oscillation ── */
.si-icon-cell:hover .uaeinw,
.icon-card:hover .uaeinw {
  animation: w0yk6x 0.8s ease;
  transform-origin: 12px 2px;
}
@keyframes w0yk6x {
  0% { transform: rotate(0); }
  10% { transform: rotate(18deg); }
  20% { transform: rotate(-16deg); }
  30% { transform: rotate(14deg); }
  40% { transform: rotate(-10deg); }
  50% { transform: rotate(7deg); }
  60% { transform: rotate(-4deg); }
  70% { transform: rotate(2deg); }
  80% { transform: rotate(-1deg); }
  100% { transform: rotate(0); }
}

/* ── 13. EYE: Blink then pupil dilates ── */
.si-icon-cell:hover .jckovp,
.icon-card:hover .jckovp {
  animation: hi9fmd 0.6s ease;
  transform-origin: center;
}
@keyframes hi9fmd {
  0% { transform: scaleY(1); }
  20% { transform: scaleY(0.05); }
  40% { transform: scaleY(1.1); }
  60% { transform: scaleY(0.95); }
  100% { transform: scaleY(1); }
}

/* ── 14. EYE-OFF: Closes shut, slash throbs ── */
.si-icon-cell:hover .gtpe9w,
.icon-card:hover .gtpe9w {
  animation: gknbhd 0.5s ease;
  transform-origin: center;
}
.si-icon-cell:hover .gtpe9w .sf-eye-off-p2,
.icon-card:hover .gtpe9w .sf-eye-off-p2 {
  animation: grm3p0 0.5s ease 0.15s both;
  transform-origin: center;
}
@keyframes gknbhd {
  0% { transform: scaleY(1); }
  30% { transform: scaleY(0.1); }
  60% { transform: scaleY(0.8); }
  100% { transform: scaleY(1); }
}
@keyframes grm3p0 {
  0%, 100% { transform: scale(1); opacity: 1; }
  40% { transform: scale(1.15); opacity: 0.5; }
}

/* ── 15. THUMB-UP: Pop up with enthusiastic bounce ── */
.si-icon-cell:hover .eozvz2,
.icon-card:hover .eozvz2 {
  animation: v5uewo 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center bottom;
}
@keyframes v5uewo {
  0% { transform: scale(1) rotate(0); }
  30% { transform: scale(1.2) rotate(-12deg); }
  60% { transform: scale(1.05) rotate(3deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 16. THUMB-DOWN: Drops with gravity ── */
.si-icon-cell:hover .nv2su4,
.icon-card:hover .nv2su4 {
  animation: rfqbew 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center top;
}
@keyframes rfqbew {
  0% { transform: scale(1) rotate(0); }
  30% { transform: scale(1.2) rotate(12deg); }
  60% { transform: scale(1.05) rotate(-3deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 17. STAR: Shooting star burst ── */
.si-icon-cell:hover .owp7es,
.icon-card:hover .owp7es {
  animation: sd2fug 0.6s ease;
  transform-origin: center;
}
@keyframes sd2fug {
  0% { transform: scale(1) rotate(0); filter: brightness(1); }
  20% { transform: scale(0.6) rotate(-30deg); filter: brightness(0.5); }
  40% { transform: scale(1.4) rotate(15deg); filter: brightness(1.5); }
  60% { transform: scale(1.1) rotate(-5deg); filter: brightness(1.2); }
  100% { transform: scale(1) rotate(0); filter: brightness(1); }
}

/* ── 18. SHIELD-CHECK: Shield shakes secure, check bounces ── */
.si-icon-cell:hover .kf21h9 .sf-shield-check-p0,
.icon-card:hover .kf21h9 .sf-shield-check-p0 {
  animation: s1warv 0.5s ease;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .kf21h9 .sf-shield-check-p1,
.icon-card:hover .kf21h9 .sf-shield-check-p1 {
  animation: nlii2s 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.2s both;
  transform-origin: 12px 13px;
}
@keyframes s1warv {
  0%, 100% { transform: scale(1) rotate(0); }
  20% { transform: scale(1.06) rotate(-4deg); }
  40% { transform: scale(1.06) rotate(4deg); }
  60% { transform: scale(1.03) rotate(-2deg); }
  80% { transform: scale(1.01) rotate(1deg); }
}
@keyframes nlii2s {
  0% { transform: scale(1) rotate(0); }
  50% { transform: scale(1.3) rotate(-10deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 19. TROPHY: Handles flash like sparkles around cup ── */
.si-icon-cell:hover .duy6zc .sf-trophy-p4,
.icon-card:hover .duy6zc .sf-trophy-p4 {
  animation: ex0sfm 0.7s ease infinite;
  transform-origin: 5px 9px;
}
.si-icon-cell:hover .duy6zc .sf-trophy-p5,
.icon-card:hover .duy6zc .sf-trophy-p5 {
  animation: c16036 0.7s ease 0.2s infinite;
  transform-origin: 19px 9px;
}
@keyframes ex0sfm {
  0%, 100% { opacity: 1; transform: scale(1); }
  30% { opacity: 0; transform: scale(0.3); }
  60% { opacity: 1; transform: scale(1.15); }
  80% { opacity: 0.5; transform: scale(0.8); }
}
@keyframes c16036 {
  0%, 100% { opacity: 1; transform: scale(1); }
  20% { opacity: 0.6; transform: scale(0.7); }
  45% { opacity: 0; transform: scale(0.2); }
  70% { opacity: 1; transform: scale(1.2); }
}

/* ── 20. SPARKLES: Only small stars blink and pulse ── */
.si-icon-cell:hover .e94pmb .sf-sparkles-p1,
.icon-card:hover .e94pmb .sf-sparkles-p1 {
  animation: sn20tt 0.6s ease infinite;
  transform-origin: 18px 6px;
}
.si-icon-cell:hover .e94pmb .sf-sparkles-p2,
.icon-card:hover .e94pmb .sf-sparkles-p2 {
  animation: v61pau 0.8s ease 0.25s infinite;
  transform-origin: 18px 18px;
}
@keyframes sn20tt {
  0%, 100% { opacity: 1; transform: scale(1); }
  35% { opacity: 0; transform: scale(0.2); }
  65% { opacity: 1; transform: scale(1.3); }
  85% { opacity: 0.4; transform: scale(0.7); }
}
@keyframes v61pau {
  0%, 100% { opacity: 1; transform: scale(1); }
  25% { opacity: 0.3; transform: scale(1.25); }
  50% { opacity: 0; transform: scale(0.15); }
  75% { opacity: 1; transform: scale(1.15); }
}

/* ── 21. POWER: Press down, glow up ── */
.si-icon-cell:hover .h65v1p,
.icon-card:hover .h65v1p {
  animation: hxv9c1 0.5s ease;
  transform-origin: center;
}
@keyframes hxv9c1 {
  0% { transform: scale(1); }
  20% { transform: scale(0.85); }
  50% { transform: scale(1.12); }
  100% { transform: scale(1); }
}

/* ── 22. TOGGLE-RIGHT: Slide right motion ── */
.si-icon-cell:hover .i65p52,
.icon-card:hover .i65p52 {
  animation: tvsfw2 0.4s ease;
}
@keyframes tvsfw2 {
  0% { transform: translateX(-4px); opacity: 0.5; }
  50% { transform: translateX(2px); opacity: 1; }
  100% { transform: translateX(0); }
}

/* ── 23. BOOKMARK: Ribbon drops from top and pins ── */
.si-icon-cell:hover .y3fb9q,
.icon-card:hover .y3fb9q {
  animation: veup4a 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center top;
}
@keyframes veup4a {
  0% { transform: translateY(-10px) scaleY(0.3); opacity: 0; }
  40% { transform: translateY(2px) scaleY(1.1); opacity: 1; }
  70% { transform: translateY(-1px) scaleY(0.98); }
  100% { transform: translateY(0) scaleY(1); }
}

/* ── 24. PINNED: Pin pushes down with rotation ── */
.si-icon-cell:hover .m0my97,
.icon-card:hover .m0my97 {
  animation: wfm8bd 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center;
}
@keyframes wfm8bd {
  0% { transform: translateY(-6px) rotate(-15deg); }
  40% { transform: translateY(2px) rotate(3deg); }
  70% { transform: translateY(-1px) rotate(-1deg); }
  100% { transform: translateY(0) rotate(0); }
}

/* ── 25. FLAG: Plants with wind ripple ── */
.si-icon-cell:hover .yc7rk2,
.icon-card:hover .yc7rk2 {
  animation: mg3ko1 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: left bottom;
}
.si-icon-cell:hover .yc7rk2 .sf-flag-p0,
.icon-card:hover .yc7rk2 .sf-flag-p0 {
  animation: m16dyu 0.8s ease 0.3s infinite;
  transform-origin: left center;
}
@keyframes mg3ko1 {
  0% { transform: rotate(-25deg) scale(0.8); opacity: 0.4; }
  40% { transform: rotate(5deg) scale(1.05); opacity: 1; }
  70% { transform: rotate(-2deg); }
  100% { transform: rotate(0) scale(1); }
}
@keyframes m16dyu {
  0%, 100% { transform: skewX(0); }
  30% { transform: skewX(-4deg); }
  70% { transform: skewX(3deg); }
}

/* ── 26. ARCHIVE: Item drops into box with lid close ── */
.si-icon-cell:hover .v47b3g,
.icon-card:hover .v47b3g {
  animation: k8nzv1 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform-origin: center bottom;
}
@keyframes k8nzv1 {
  0% { transform: translateY(-8px) scale(0.8); opacity: 0.3; }
  30% { transform: translateY(2px) scale(1.08); opacity: 1; }
  50% { transform: translateY(-1px) scale(0.96); }
  70% { transform: translateY(1px) scale(1.02); }
  100% { transform: translateY(0) scale(1); }
}

/* ── 27. TRASH: Lid pops, bin tips and falls ── */
.si-icon-cell:hover .xe1ydo,
.icon-card:hover .xe1ydo {
  animation: pc6sfd 0.6s ease;
  transform-origin: center bottom;
}
@keyframes pc6sfd {
  0% { transform: rotate(0) translateY(0); }
  15% { transform: rotate(-15deg) translateY(-2px); }
  30% { transform: rotate(12deg) translateY(-1px); }
  45% { transform: rotate(-8deg); }
  60% { transform: rotate(4deg); }
  75% { transform: rotate(-2deg); }
  90% { transform: rotate(0.5deg); }
  100% { transform: rotate(0) translateY(0); }
}

/* ── 28. SEND: Paper plane launches diagonally then returns ── */
.si-icon-cell:hover .hy1mww,
.icon-card:hover .hy1mww {
  animation: bqp3us 0.6s ease;
  transform-origin: center;
}
@keyframes bqp3us {
  0% { transform: translate(0, 0) scale(1) rotate(0); }
  30% { transform: translate(6px, -6px) scale(0.7) rotate(5deg); opacity: 0.4; }
  50% { transform: translate(8px, -8px) scale(0.5); opacity: 0; }
  51% { transform: translate(-4px, 4px) scale(0.5); opacity: 0; }
  70% { transform: translate(-1px, 1px) scale(1.1); opacity: 1; }
  100% { transform: translate(0, 0) scale(1) rotate(0); }
}

/* ── 29. CLOUD-CHECK: Cloud floats, check bounces ── */
.si-icon-cell:hover .to055j .sf-cloud-check-p0,
.icon-card:hover .to055j .sf-cloud-check-p0 {
  animation: gcxs1t 1s ease infinite;
}
.si-icon-cell:hover .to055j .sf-cloud-check-p1,
.icon-card:hover .to055j .sf-cloud-check-p1 {
  animation: l45ss5 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.2s both;
  transform-origin: 12px 15px;
}
@keyframes gcxs1t {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}
@keyframes l45ss5 {
  0% { transform: scale(1) rotate(0); }
  50% { transform: scale(1.3) rotate(-8deg); }
  100% { transform: scale(1) rotate(0); }
}

/* ── 30. WIFI: Signal waves cascade outward ── */
.si-icon-cell:hover .z5ay37 .sf-wifi-p0,
.icon-card:hover .z5ay37 .sf-wifi-p0 {
  animation: huay8k 0.8s ease 0s infinite;
}
.si-icon-cell:hover .z5ay37 .sf-wifi-p1,
.icon-card:hover .z5ay37 .sf-wifi-p1 {
  animation: huay8k 0.8s ease 0.15s infinite;
}
.si-icon-cell:hover .z5ay37 .sf-wifi-p2,
.icon-card:hover .z5ay37 .sf-wifi-p2 {
  animation: huay8k 0.8s ease 0.3s infinite;
}
.si-icon-cell:hover .z5ay37 .sf-wifi-p3,
.icon-card:hover .z5ay37 .sf-wifi-p3 {
  animation: huay8k 0.8s ease 0.45s infinite;
}
@keyframes huay8k {
  0% { opacity: 0.1; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.05); }
  100% { opacity: 0.1; transform: scale(0.8); }
